 await page.getByRole('button',{name:'Nova conta',exact:true}).click();const form=page.getByRole('dialog',{name:'Nova conta',exact:true}).locator('form');await form.getByPlaceholder('Nome da conta').fill('Reserva');await form.getByPlaceholder('Saldo inicial').fill('100');await form.getByLabel('Finalidade').selectOption('recurring');const request=page.waitForRequest(r=>r.url().endsWith('/rpc/save_account'));await form.getByRole('button',{name:'Salvar conta'}).click();expect((await request).postDataJSON()).toMatchObject({p_name:'Reserva',p_type:'recurring'});await expect(form).toBeHidden();
