const currentDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayOffset=n=>{const d=new Date(currentDate()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const nextMonth=month=>{const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+1);return d.toISOString().slice(0,7)};
const monthText=month=>new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z'));
const movement=(id,title,days,status='pending',kind='expense')=>({id,title,due_date:dayOffset(days),status,kind,amount:100,paid_amount:status==='settled'?100:0,owner_id:ana,account_id:'a',category:'Moradia'});
test('pendências mensais têm uma lista rolável, setas, filtros e checklist',async({page})=>{
 await page.setViewportSize({width:390,height:844});const month=currentDate().slice(0,7),next=nextMonth(month),rows=Array.from({length:15},(_,i)=>({...movement('row'+i,'Conta '+String(i+1).padStart(2,'0'),0),due_date:month+'-'+String(i+1).padStart(2,'0')}));await seed(page,{eventRows:[...rows,{...movement('future','Próximo mês',0),due_date:next+'-10'}]});await page.getByRole('tab',{name:'Transações',exact:true}).click();const pending=page.locator('#screen-pending');await expect(pending.locator('.pending-scroll')).toHaveCount(1);await pending.getByText('Filtrar transações',{exact:true}).click();await pending.getByLabel('Status',{exact:true}).selectOption('all');await expect(pending.locator('.pending-scroll article')).toHaveCount(15);await expect(pending.getByRole('button',{name:/Ver dias seguintes|Ocultar/})).toHaveCount(0);await expect(pending.getByText('Próximo mês',{exact:true})).toHaveCount(0);
 const scroll=pending.locator('.pending-scroll');const dimensions=await scroll.evaluate(el=>({height:el.clientHeight,content:el.scrollHeight,row:el.querySelector('article').getBoundingClientRect().height}));expect(dimensions.height).toBeLessThanOrEqual(dimensions.row*10+1);expect(dimensions.content).toBeGreaterThan(dimensions.height);await page.screenshot({path:'test-results/pendencias-lista-mobile.png'});await scroll.evaluate(el=>{el.scrollTop=el.scrollHeight});await pending.getByRole('button',{name:'Próximo mês das transações'}).click();await expect(pending.getByText('Próximo mês',{exact:true})).toBeVisible();await expect(pending.locator('.pending-scroll article')).toHaveCount(1);await expect(scroll).toHaveJSProperty('scrollTop',0);await page.reload();await expect(page.getByRole('tab',{name:'Transações',exact:true})).toHaveAttribute('aria-selected','true');await expect(pending.getByText('Próximo mês',{exact:true})).toBeVisible();await pending.getByRole('button',{name:'Mês anterior das transações'}).click();await pending.getByText('Filtrar transações',{exact:true}).click();await pending.getByLabel('Status',{exact:true}).selectOption('all');await expect(pending.locator('.pending-scroll article')).toHaveCount(15);await pending.getByPlaceholder('Nome ou categoria').fill('Conta 01');await expect(pending.locator('.total-balance')).toContainText('R$ 100,00');
 const download=page.waitForEvent('download');await pending.getByRole('button',{name:'Baixar checklist',exact:true}).click();expect((await download).suggestedFilename()).toBe('despesas-'+month+'.txt');await expect(page.locator('body')).toHaveJSProperty('scrollWidth',390);await page.screenshot({path:'test-results/pendencias-mensais-mobile.png'});
});
