test('categorias padrão podem ser editadas e excluídas sem reaparecer no cadastro',async({page})=>{
 await seed(page);let rows=[{id:'expense-default',name:'Outros',kind:'expense',color:'#e11d48',icon:'wallet',active:true}];await page.route('**/rest/v1/categories?**',async route=>{if(route.request().method()==='PATCH'){rows=rows.map(r=>({...r,...route.request().postDataJSON()}));return route.fulfill({status:204})}return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(rows.filter(r=>!r.deleted_at))})});await page.route('**/rest/v1/rpc/delete_category',route=>{rows=rows.map(r=>({...r,active:false,deleted_at:new Date().toISOString()}));return route.fulfill({status:200,contentType:'application/json',body:'null'})});
 await page.getByRole('tab',{name:'Mais',exact:true}).click();await page.getByRole('button',{name:'Personalização',exact:true}).click();await page.getByRole('button',{name:'Selecionar categoria Outros',exact:true}).click();await page.getByRole('button',{name:'Editar categoria Outros despesa'}).click();const prefs=page.locator('#preferences');await prefs.getByLabel('Categoria',{exact:true}).fill('Casa');await prefs.getByRole('button',{name:'Salvar categoria'}).click();await expect(prefs.getByRole('button',{name:'Excluir categoria Casa despesa'})).toBeVisible();await prefs.getByRole('button',{name:'Excluir categoria Casa despesa'}).click();await expect(prefs.getByRole('button',{name:'Excluir categoria Casa despesa'})).toHaveCount(0);await openEntry(page);await expect(page.locator('#new-entry select[name="category"] option')).toHaveCount(0);
});
