test('tocar no saldo abre ajuste simples e atualiza o valor da conta',async({page})=>{
 await page.setViewportSize({width:390,height:844});await seed(page);let currentAccounts=accounts.map(a=>({...a}));
 await page.route('**/rest/v1/financial_accounts?**',route=>route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(currentAccounts)}));
 await page.route('**/rest/v1/rpc/adjust_account_balance',route=>{const args=route.request().postDataJSON();currentAccounts=currentAccounts.map(a=>a.id===args.p_account?{...a,balance:args.p_balance}:a);return route.fulfill({status:200,contentType:'application/json',body:'null'})});
 await page.getByRole('tab',{name:'Contas',exact:true}).click();await page.getByRole('button',{name:'Ajustar saldo de Conta Ana',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Ajustar saldo',exact:true});await expect(dialog.locator('input')).toHaveCount(1);await expect(dialog.getByLabel('Novo saldo')).toBeFocused();await expect(dialog.getByLabel('Novo saldo')).toHaveValue('1000');await dialog.getByLabel('Novo saldo').fill('1234.56');
 const request=page.waitForRequest(r=>r.url().endsWith('/rpc/adjust_account_balance'));await dialog.getByRole('button',{name:'Salvar saldo',exact:true}).click();expect((await request).postDataJSON()).toMatchObject({p_account:'a',p_balance:1234.56,p_expected_balance:1000});await expect(dialog).toBeHidden();await expect(page.getByRole('button',{name:'Ajustar saldo de Conta Ana',exact:true})).toContainText('1.234,56');
});
